{
  "sop_id": "schedule-payment",
  "milestones": [
    {
      "id": "M1",
      "target": "A payment request is created for the invoice with status 'pending_approval'.",
      "sop_step": "SP-3",
      "predicates": [
        {
          "read": "list_payments",
          "args": {
            "invoice": 9
          },
          "where": {
            "invoice_id": 9,
            "status": "pending_approval"
          },
          "expect": {
            "vendor_name": "Sharma Logistics Pvt Ltd"
          }
        }
      ],
      "judge": [
        "The payment request is correctly linked to the invoice.",
        "The status is set to pending_approval as required."
      ]
    },
    {
      "id": "M2",
      "target": "A business approval request is created for the payment request.",
      "sop_step": "SP-4",
      "awaits_business_approval": true,
      "predicates": [
        {
          "read": "list_approvals",
          "where": {
            "entity_id": {
              "ref": "M1"
            },
            "entity_type": "payment",
            "status": "pending"
          }
        }
      ],
      "judge": [
        "The approval request is linked to the payment request.",
        "The approval status is pending."
      ]
    },
    {
      "id": "M3",
      "target": "No other payment requests exist for this invoice.",
      "sop_step": "SP-2",
      "predicates": [
        {
          "read": "list_payments",
          "args": {
            "invoice": 9
          },
          "where": {
            "invoice_id": 9,
            "status": "paid"
          },
          "count": 0
        }
      ]
    }
  ]
}

